"use strict";
class Packet extends Error {
  constructor({ message, code, shelf }) {
    super(message);
    this.code = code;
    this.shelf = shelf;
  }
  // Calls the (possibly overridden) label with no argument and with two.
  describe(prefix) {
    return (prefix === undefined ? "" : prefix) + this.label() + "/" + this.label("x", 2);
  }
  label(mark, times) {
    return this.code + String(mark) + String(times);
  }
}

class Tray {
  constructor(rows, cols) {
    this.rows = rows;
    this.cols = cols;
  }
  size() {
    return String(this.rows) + "x" + String(this.cols);
  }
  each(visit) {
    return [visit.call(this, 1), visit.call(this, 2, "b")].join(",");
  }
}

exports.Packet = Packet;
exports.Tray = Tray;
